CREATE TABLE firms(id uuid PRIMARY KEY, name text NOT NULL, timezone text NOT NULL DEFAULT 'America/Lima', currency text NOT NULL DEFAULT 'PEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, firm_id uuid NOT NULL REFERENCES firms, person_id uuid NOT NULL, subject text UNIQUE, email text NOT NULL, name text NOT NULL, role text NOT NULL CHECK(role IN ('superadmin','manager','lawyer','assistant','client')), active boolean NOT NULL DEFAULT true, session_version integer NOT NULL DEFAULT 1, version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id), UNIQUE(firm_id,email));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, session_version integer NOT NULL, csrf_hash text NOT NULL, mfa boolean NOT NULL, expires_at timestamptz NOT NULL, last_seen timestamptz NOT NULL DEFAULT now());
CREATE TABLE login_states(state_hash text PRIMARY KEY, verifier text NOT NULL, nonce text NOT NULL, invitation_hash text, expires_at timestamptz NOT NULL);
CREATE TABLE invitations(id uuid PRIMARY KEY, firm_id uuid NOT NULL REFERENCES firms, token_hash text NOT NULL UNIQUE, email text NOT NULL, name text NOT NULL, role text NOT NULL CHECK(role IN ('superadmin','manager','lawyer','assistant','client')), expires_at timestamptz NOT NULL, consumed_at timestamptz, created_by uuid NOT NULL, FOREIGN KEY(created_by,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE clients(id uuid PRIMARY KEY, firm_id uuid NOT NULL REFERENCES firms, name text NOT NULL, type text NOT NULL CHECK(type IN ('person','company')), document_type text, document_number text, archived boolean NOT NULL DEFAULT false, data jsonb NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id));
CREATE UNIQUE INDEX clients_document_unique ON clients(firm_id,document_type,document_number) WHERE document_number IS NOT NULL;
CREATE TABLE client_memberships(user_id uuid NOT NULL, client_id uuid NOT NULL, firm_id uuid NOT NULL, PRIMARY KEY(user_id,client_id), FOREIGN KEY(user_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(client_id,firm_id) REFERENCES clients(id,firm_id));
CREATE TABLE client_creation_grants(user_id uuid NOT NULL, client_id uuid NOT NULL, firm_id uuid NOT NULL, PRIMARY KEY(user_id,client_id), FOREIGN KEY(user_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(client_id,firm_id) REFERENCES clients(id,firm_id));
CREATE TABLE projects(id uuid PRIMARY KEY, firm_id uuid NOT NULL REFERENCES firms, client_id uuid NOT NULL, code text NOT NULL, name text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','suspended','closed')), owner_id uuid NOT NULL, partner_id uuid NOT NULL, lead_id uuid NOT NULL, conflict_status text NOT NULL DEFAULT 'pending', data jsonb NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id), UNIQUE(firm_id,code), FOREIGN KEY(client_id,firm_id) REFERENCES clients(id,firm_id), FOREIGN KEY(owner_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(partner_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(lead_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE project_grants(id uuid PRIMARY KEY, firm_id uuid NOT NULL, project_id uuid NOT NULL, user_id uuid NOT NULL, economic boolean NOT NULL DEFAULT false, valid_until timestamptz, UNIQUE(project_id,user_id), FOREIGN KEY(project_id,firm_id) REFERENCES projects(id,firm_id), FOREIGN KEY(user_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE conflict_reviews(id uuid PRIMARY KEY, firm_id uuid NOT NULL, project_id uuid NOT NULL, reviewer_id uuid NOT NULL, result text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,firm_id) REFERENCES projects(id,firm_id), FOREIGN KEY(reviewer_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE cases(id uuid PRIMARY KEY, firm_id uuid NOT NULL, project_id uuid NOT NULL, code text NOT NULL, title text NOT NULL, type text NOT NULL CHECK(type IN ('judicial','extrajudicial')), status text NOT NULL DEFAULT 'open' CHECK(status IN ('draft','open','in_progress','suspended','closed')), responsible_id uuid NOT NULL, followup_id uuid NOT NULL, backup_id uuid NOT NULL, parent_id uuid, judicial_number text, authority text, archived boolean NOT NULL DEFAULT false, data jsonb NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1, CHECK(followup_id<>backup_id), CHECK(parent_id IS DISTINCT FROM id), UNIQUE(id,firm_id), UNIQUE(id,firm_id,project_id), UNIQUE(firm_id,code), FOREIGN KEY(project_id,firm_id) REFERENCES projects(id,firm_id), FOREIGN KEY(responsible_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(followup_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(backup_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(parent_id,firm_id,project_id) REFERENCES cases(id,firm_id,project_id));
CREATE UNIQUE INDEX judicial_case_unique ON cases(firm_id,judicial_number,authority) WHERE judicial_number IS NOT NULL;
CREATE TABLE case_grants(id uuid PRIMARY KEY, firm_id uuid NOT NULL, case_id uuid NOT NULL, user_id uuid NOT NULL, actions text[] NOT NULL, valid_from timestamptz NOT NULL, valid_until timestamptz, revoked_at timestamptz, granted_by uuid NOT NULL, reason text NOT NULL, version integer NOT NULL DEFAULT 1, CHECK(valid_until IS NULL OR valid_until>valid_from), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id), FOREIGN KEY(user_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(granted_by,firm_id) REFERENCES users(id,firm_id));
CREATE INDEX grants_effective ON case_grants(firm_id,user_id,case_id) WHERE revoked_at IS NULL;
CREATE TABLE case_assignments(id uuid PRIMARY KEY, firm_id uuid NOT NULL, case_id uuid NOT NULL, user_id uuid NOT NULL, function text NOT NULL, valid_from timestamptz NOT NULL DEFAULT now(), valid_until timestamptz, granted_by uuid NOT NULL, reason text NOT NULL, replaces_id uuid REFERENCES case_assignments, data jsonb NOT NULL DEFAULT '{}', FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id), FOREIGN KEY(user_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(granted_by,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE activities(id uuid PRIMARY KEY, firm_id uuid NOT NULL, case_id uuid NOT NULL, revision_id uuid NOT NULL, author_id uuid NOT NULL, data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id), FOREIGN KEY(author_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE activity_revisions(id uuid PRIMARY KEY, firm_id uuid NOT NULL, activity_id uuid NOT NULL, author_id uuid NOT NULL, data jsonb NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(activity_id,firm_id) REFERENCES activities(id,firm_id), FOREIGN KEY(author_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE documents(id uuid PRIMARY KEY, firm_id uuid NOT NULL, case_id uuid NOT NULL, title text NOT NULL, classification text NOT NULL CHECK(classification IN ('operational','financial')), status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','removed','restricted')), current_version_id uuid, version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id));
CREATE TABLE document_versions(id uuid PRIMARY KEY, firm_id uuid NOT NULL, document_id uuid NOT NULL, sequence integer NOT NULL CHECK(sequence>0), author_id uuid NOT NULL, object_key text NOT NULL UNIQUE, preview_key text, sha256 text NOT NULL, mime text NOT NULL, size_bytes bigint NOT NULL, review_status text NOT NULL CHECK(review_status IN ('pending','reviewed')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,firm_id), UNIQUE(document_id,sequence), FOREIGN KEY(document_id,firm_id) REFERENCES documents(id,firm_id), FOREIGN KEY(author_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE uploads(id uuid PRIMARY KEY, firm_id uuid NOT NULL, case_id uuid NOT NULL, requested_by uuid NOT NULL, object_key text NOT NULL UNIQUE, document_id uuid, status text NOT NULL DEFAULT 'quarantine', data jsonb NOT NULL, sha256 text, preview_key text, error_code text, version integer NOT NULL DEFAULT 1, expires_at timestamptz NOT NULL DEFAULT now()+interval '1 day', UNIQUE(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id), FOREIGN KEY(requested_by,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(document_id,firm_id) REFERENCES documents(id,firm_id));
CREATE TABLE publications(id uuid PRIMARY KEY, firm_id uuid NOT NULL, case_id uuid NOT NULL, activity_revision_id uuid REFERENCES activity_revisions, document_version_id uuid, author_id uuid NOT NULL, published_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, version integer NOT NULL DEFAULT 1, CHECK((activity_revision_id IS NULL)<>(document_version_id IS NULL)), UNIQUE(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id), FOREIGN KEY(document_version_id,firm_id) REFERENCES document_versions(id,firm_id), FOREIGN KEY(author_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE publication_audiences(publication_id uuid NOT NULL, user_id uuid NOT NULL, firm_id uuid NOT NULL, PRIMARY KEY(publication_id,user_id), FOREIGN KEY(publication_id,firm_id) REFERENCES publications(id,firm_id), FOREIGN KEY(user_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE tasks(id uuid PRIMARY KEY, firm_id uuid NOT NULL, case_id uuid NOT NULL, assignee_id uuid NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','in_progress','completed','cancelled')), data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id), FOREIGN KEY(assignee_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE hearings(id uuid PRIMARY KEY, firm_id uuid NOT NULL, case_id uuid NOT NULL, data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id));
CREATE TABLE notices(id uuid PRIMARY KEY, firm_id uuid NOT NULL, case_id uuid NOT NULL, registered_by uuid NOT NULL, support_version_id uuid, received_at timestamptz NOT NULL, registered_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'untreated', data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id), FOREIGN KEY(registered_by,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(support_version_id,firm_id) REFERENCES document_versions(id,firm_id));
CREATE TABLE deadlines(id uuid PRIMARY KEY, firm_id uuid NOT NULL, case_id uuid NOT NULL, notice_id uuid NOT NULL, registered_by uuid NOT NULL, verified_by uuid, revision_id uuid NOT NULL, status text NOT NULL DEFAULT 'pending_verification' CHECK(status IN ('pending_verification','active','filed','overdue_unfiled','cancelled')), due_on date NOT NULL, responsible_id uuid NOT NULL, backup_id uuid NOT NULL, data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, CHECK(responsible_id<>backup_id), UNIQUE(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id), FOREIGN KEY(notice_id,firm_id) REFERENCES notices(id,firm_id), FOREIGN KEY(registered_by,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(verified_by,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(responsible_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(backup_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE deadline_revisions(id uuid PRIMARY KEY, firm_id uuid NOT NULL, deadline_id uuid NOT NULL, author_id uuid NOT NULL, data jsonb NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(deadline_id,firm_id) REFERENCES deadlines(id,firm_id), FOREIGN KEY(author_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE calendars(id uuid PRIMARY KEY, firm_id uuid NOT NULL REFERENCES firms, name text NOT NULL, timezone text NOT NULL DEFAULT 'America/Lima', non_working_dates date[] NOT NULL DEFAULT '{}', approved boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id));
CREATE TABLE mailboxes(id uuid PRIMARY KEY, firm_id uuid NOT NULL REFERENCES firms, responsible_id uuid NOT NULL, backup_id uuid NOT NULL, supervisor_id uuid NOT NULL, calendar_id uuid NOT NULL, data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, CHECK(responsible_id<>backup_id), UNIQUE(id,firm_id), FOREIGN KEY(responsible_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(backup_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(supervisor_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(calendar_id,firm_id) REFERENCES calendars(id,firm_id));
CREATE TABLE daily_checks(id uuid PRIMARY KEY, firm_id uuid NOT NULL, mailbox_id uuid NOT NULL, checked_by uuid NOT NULL, date date NOT NULL, notice_count integer NOT NULL CHECK(notice_count>=0), observation text, UNIQUE(mailbox_id,date), FOREIGN KEY(mailbox_id,firm_id) REFERENCES mailboxes(id,firm_id), FOREIGN KEY(checked_by,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE deliveries(id uuid PRIMARY KEY, firm_id uuid NOT NULL, user_id uuid NOT NULL, event_key text NOT NULL UNIQUE, case_id uuid, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, last_attempt_at timestamptz, data jsonb NOT NULL DEFAULT '{}', FOREIGN KEY(user_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id));
CREATE TABLE imports(id uuid PRIMARY KEY, firm_id uuid NOT NULL REFERENCES firms, requested_by uuid NOT NULL, source_hash text NOT NULL, object_key text NOT NULL, status text NOT NULL DEFAULT 'uploaded', data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id), UNIQUE(firm_id,source_hash), FOREIGN KEY(requested_by,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE import_rows(id uuid PRIMARY KEY, firm_id uuid NOT NULL, import_id uuid NOT NULL, row_number integer NOT NULL, project_group text NOT NULL, status text NOT NULL, data jsonb NOT NULL, error_code text, created_id uuid, UNIQUE(import_id,row_number), FOREIGN KEY(import_id,firm_id) REFERENCES imports(id,firm_id));
CREATE TABLE costs(id uuid PRIMARY KEY, firm_id uuid NOT NULL, case_id uuid NOT NULL, activity_id uuid, registered_by uuid NOT NULL, approved_by uuid, original_cost_id uuid, description text NOT NULL, currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'), quantity numeric(18,4) NOT NULL CHECK(quantity>0), unit_price numeric(18,4) NOT NULL, amount numeric(18,2) NOT NULL, approval text NOT NULL DEFAULT 'registered' CHECK(approval IN ('registered','approved','rejected')), billing text NOT NULL DEFAULT 'pending' CHECK(billing IN ('pending','reserved','invoiced','cancelled')), data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, CHECK(original_cost_id IS NOT NULL OR unit_price>=0), CHECK(approved_by IS NULL OR approved_by<>registered_by), UNIQUE(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id), FOREIGN KEY(activity_id,firm_id) REFERENCES activities(id,firm_id), FOREIGN KEY(registered_by,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(approved_by,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(original_cost_id,firm_id) REFERENCES costs(id,firm_id));
CREATE TABLE billing_drafts(id uuid PRIMARY KEY, firm_id uuid NOT NULL, project_id uuid NOT NULL, currency text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','cancelled','confirmed')), created_by uuid NOT NULL, version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id), FOREIGN KEY(project_id,firm_id) REFERENCES projects(id,firm_id), FOREIGN KEY(created_by,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE billing_lines(id uuid PRIMARY KEY, firm_id uuid NOT NULL, draft_id uuid NOT NULL, cost_id uuid NOT NULL, case_id uuid NOT NULL, description text NOT NULL, quantity numeric(18,4) NOT NULL, unit_price numeric(18,4) NOT NULL, amount numeric(18,2) NOT NULL, FOREIGN KEY(draft_id,firm_id) REFERENCES billing_drafts(id,firm_id), FOREIGN KEY(cost_id,firm_id) REFERENCES costs(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id));
CREATE TABLE reservations(cost_id uuid PRIMARY KEY, firm_id uuid NOT NULL, draft_id uuid NOT NULL, FOREIGN KEY(cost_id,firm_id) REFERENCES costs(id,firm_id), FOREIGN KEY(draft_id,firm_id) REFERENCES billing_drafts(id,firm_id));
CREATE TABLE invoice_references(id uuid PRIMARY KEY, firm_id uuid NOT NULL, draft_id uuid NOT NULL UNIQUE, data jsonb NOT NULL, version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id), FOREIGN KEY(draft_id,firm_id) REFERENCES billing_drafts(id,firm_id));
CREATE TABLE payments(id uuid PRIMARY KEY, firm_id uuid NOT NULL, invoice_id uuid NOT NULL, amount numeric(18,2) NOT NULL, currency text NOT NULL, date date NOT NULL, reference text NOT NULL, reverses_id uuid UNIQUE, created_by uuid NOT NULL, CHECK((amount>0 AND reverses_id IS NULL) OR (amount<0 AND reverses_id IS NOT NULL)), UNIQUE(id,firm_id), FOREIGN KEY(invoice_id,firm_id) REFERENCES invoice_references(id,firm_id), FOREIGN KEY(reverses_id,firm_id) REFERENCES payments(id,firm_id), FOREIGN KEY(created_by,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE audit_events(id uuid PRIMARY KEY, firm_id uuid NOT NULL REFERENCES firms, actor_id uuid NOT NULL, person_id uuid NOT NULL, case_id uuid, resource_id uuid NOT NULL, action text NOT NULL, economic boolean NOT NULL DEFAULT false, occurred_at timestamptz NOT NULL DEFAULT now(), result text NOT NULL DEFAULT 'success', reason text, before_data jsonb, after_data jsonb, FOREIGN KEY(actor_id,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id));
CREATE FUNCTION immutable_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit is immutable'; END $$;
CREATE TRIGGER audit_no_update BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_audit();
CREATE TABLE jobs(id uuid PRIMARY KEY, firm_id uuid NOT NULL REFERENCES firms, requested_by uuid NOT NULL, case_id uuid, kind text NOT NULL, resource_id uuid NOT NULL, dedupe_key text UNIQUE, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), leased_until timestamptz, lease_token uuid, error_code text, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,firm_id), FOREIGN KEY(requested_by,firm_id) REFERENCES users(id,firm_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id));
CREATE INDEX jobs_pending ON jobs(available_at) WHERE status IN ('queued','processing');
CREATE TABLE ocr_jobs(id uuid PRIMARY KEY, firm_id uuid NOT NULL, source_version_id uuid NOT NULL, requested_by uuid NOT NULL, status text NOT NULL DEFAULT 'queued', engine text, engine_version text, error_code text, revision integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id), FOREIGN KEY(source_version_id,firm_id) REFERENCES document_versions(id,firm_id), FOREIGN KEY(requested_by,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE ocr_pages(id uuid PRIMARY KEY, firm_id uuid NOT NULL, job_id uuid NOT NULL, page integer NOT NULL CHECK(page>0), raw_text text NOT NULL, reviewed_text text, confidence numeric CHECK(confidence>=0 AND confidence<=1), reviewed_by uuid, reason text, history jsonb NOT NULL DEFAULT '[]', UNIQUE(job_id,page), FOREIGN KEY(job_id,firm_id) REFERENCES ocr_jobs(id,firm_id), FOREIGN KEY(reviewed_by,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE reports(id uuid PRIMARY KEY, firm_id uuid NOT NULL, project_id uuid NOT NULL, requested_by uuid NOT NULL, status text NOT NULL DEFAULT 'pending', partial boolean NOT NULL, expires_at timestamptz NOT NULL, data jsonb NOT NULL, FOREIGN KEY(project_id,firm_id) REFERENCES projects(id,firm_id), FOREIGN KEY(requested_by,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE deletion_requests(id uuid PRIMARY KEY, firm_id uuid NOT NULL, document_id uuid NOT NULL, requested_by uuid NOT NULL, status text NOT NULL DEFAULT 'requested', reason text NOT NULL, version integer NOT NULL DEFAULT 1, UNIQUE(id,firm_id), FOREIGN KEY(document_id,firm_id) REFERENCES documents(id,firm_id), FOREIGN KEY(requested_by,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE idempotency_records(firm_id uuid NOT NULL, actor_id uuid NOT NULL, operation text NOT NULL, key text NOT NULL, body_hash text NOT NULL, response jsonb NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '1 day', PRIMARY KEY(actor_id,operation,key), FOREIGN KEY(actor_id,firm_id) REFERENCES users(id,firm_id));
CREATE TABLE rate_limits(bucket text PRIMARY KEY, window_start timestamptz NOT NULL, hits integer NOT NULL);
